10	import type { LineClient, WhatsAppClients } from "./types";
11	
12	const log = createLogger("spectrum.whatsapp.auth");
13	const streamLog = createLogger("spectrum.whatsapp.stream");
14	
15	const RENEWAL_RATIO = 0.8;
16	const EXPIRY_BUFFER_MS = 30_000;
17	const RETRY_DELAY_MS = 30_000;
18	const RESUBSCRIBE_BACKOFF_MS = 500;
19	
20	const ignoreCleanupError = () => undefined;
21	
22	interface CloudAuth {
23	  dispose: () => Promise<void>;
24	}
25	
26	interface LineSubscription {
27	  close: () => void;
28	  swap: () => void;
29	}
