31	interface LineState {
32	  current: WhatsAppClient;
33	  subscriptions: Set<LineSubscription>;
34	}
35	
36	const cloudAuthState = new WeakMap<WhatsAppClients, CloudAuth>();
37	
38	// Cloud mode can grow lines at runtime (a token refresh may return a
39	// phoneNumberId that wasn't in the original payload). Listeners let the
40	// message stream subscribe to lines added after startup.
41	type LineAddedListener = (entry: LineClient) => void;
42	const lineListeners = new WeakMap<WhatsAppClients, Set<LineAddedListener>>();
43	
44	export const subscribeLineAdded = (
45	  clients: WhatsAppClients,
46	  listener: LineAddedListener
47	): (() => void) | undefined => {
48	  const listeners = lineListeners.get(clients);
49	  if (!listeners) {
50	    return;
51	  }
52	  listeners.add(listener);
53	  return () => {
54	    listeners.delete(listener);
55	  };
56	};
