58	// `@photon-ai/whatsapp-business` 0.1.x does not accept a token callback, so we
59	// recreate the underlying client before each RPC when the token is near expiry,
60	// and transparently re-subscribe long-lived event streams across swaps.
61	export async function createCloudClients(
62	  projectId: string,
63	  projectSecret: string
64	): Promise<WhatsAppClients> {
65	  let tokenData = await cloud.issueWhatsappBusinessTokens(
66	    projectId,
67	    projectSecret
68	  );
69	  let tokenExpiresAt = Date.now() + tokenData.expiresIn * 1000;
70	  let disposed = false;
71	  let renewalTimer: ReturnType<typeof setTimeout> | undefined;
72	  let refreshFailures = 0;
73	  let refreshInFlight: Promise<void> | undefined;
74	
75	  const lines = new Map<string, LineState>();
76	
77	  const buildRawClient = (phoneNumberId: string): WhatsAppClient => {
78	    const accessToken = tokenData.auth[phoneNumberId];
79	    if (!accessToken) {
80	      throw new Error(
81	        `WhatsApp Business line ${phoneNumberId} missing from token response`
82	      );
83	    }
84	    return createClient({ accessToken, appSecret: "", phoneNumberId });
85	  };
86	
87	  const refreshTokens = async (): Promise<void> => {
88	    tokenData = await cloud.issueWhatsappBusinessTokens(
89	      projectId,
90	      projectSecret
91	    );
92	    tokenExpiresAt = Date.now() + tokenData.expiresIn * 1000;
93	
94	    for (const [phoneNumberId, state] of lines) {
95	      if (!tokenData.auth[phoneNumberId]) {
96	        continue;
97	      }
98	      const old = state.current;
99	      state.current = buildRawClient(phoneNumberId);
100	      for (const sub of state.subscriptions) {
101	        sub.swap();
102	      }
103	      await old.close().catch(() => undefined);
104	    }
105	
106	    // A line added to the project after startup shows up as a new
107	    // phoneNumberId in the refreshed payload: give it a client, expose it for
108	    // outbound routing, and let subscribed message streams pick it up.
109	    for (const phoneNumberId of Object.keys(tokenData.auth)) {
110	      if (lines.has(phoneNumberId) || disposed) {
111	        continue;
112	      }
113	      const entry = addLine(phoneNumberId);
114	      clients.push(entry);
115	      log.info("whatsapp line added at runtime", {
116	        "spectrum.whatsapp.line": phoneNumberId,
117	      });
118	      for (const listener of listeners) {
119	        listener(entry);
120	      }
121	    }
122	  };
123	
124	  const onRefreshSuccess = () => {
125	    if (refreshFailures > 0) {
126	      log.info("whatsapp token refresh recovered", {
127	        "spectrum.whatsapp.auth.attempt": refreshFailures,
128	      });
129	      refreshFailures = 0;
130	    }
131	  };
132	
133	  const onRefreshFailure = (error: unknown) => {
134	    refreshFailures += 1;
135	    log.warn(
136	      "whatsapp token refresh failed; retrying",
137	      {
138	        "spectrum.whatsapp.auth.attempt": refreshFailures,
139	        "spectrum.whatsapp.auth.retry_in_ms": RETRY_DELAY_MS,
140	        ...errorAttrs(error),
141	      },
142	      error
143	    );
144	  };
145	
146	  const clearRenewalTimer = () => {
147	    if (renewalTimer !== undefined) {
148	      clearTimeout(renewalTimer);
149	      renewalTimer = undefined;
150	    }
151	  };
152	
153	  const refreshNow = async (): Promise<void> => {
154	    await refreshTokens();
155	    onRefreshSuccess();
156	    scheduleRenewal();
157	  };
158	
159	  const coalescedRefresh = (): Promise<void> => {
160	    if (!refreshInFlight) {
161	      refreshInFlight = refreshNow().finally(() => {
162	        refreshInFlight = undefined;
163	      });
164	    }
165	    return refreshInFlight;
166	  };
167	
168	  const scheduleRenewal = () => {
169	    if (disposed) {
170	      return;
171	    }
172	    clearRenewalTimer();
173	    const ttlMs = tokenData.expiresIn * 1000;
174	    const renewInMs = Math.max(ttlMs * RENEWAL_RATIO, 5000);
175	
176	    const runScheduledRefresh = () => {
177	      coalescedRefresh().catch((err) => {
178	        onRefreshFailure(err);
179	        if (disposed) {
180	          return;
181	        }
182	        renewalTimer = setTimeout(runScheduledRefresh, RETRY_DELAY_MS);
183	        renewalTimer?.unref?.();
184	      });
185	    };
186	
187	    renewalTimer = setTimeout(runScheduledRefresh, renewInMs);
188	    renewalTimer?.unref?.();
189	  };
190	
191	  const refreshIfNeeded = async (): Promise<void> => {
192	    if (Date.now() < tokenExpiresAt - EXPIRY_BUFFER_MS) {
193	      return;
194	    }
195	    await coalescedRefresh();
196	  };
197	
198	  scheduleRenewal();
199	
200	  // The proxy (not `state.current`, which is swapped on token refresh) is the
201	  // stable per-line handle carried in the LineClient entry.
202	  const addLine = (phoneNumberId: string): LineClient => {
203	    const state: LineState = {
204	      current: buildRawClient(phoneNumberId),
205	      subscriptions: new Set(),
206	    };
207	    lines.set(phoneNumberId, state);
208	    return {
209	      client: buildClientProxy(state, refreshIfNeeded),
210	      line: phoneNumberId,
211	    };
212	  };
213	
214	  const clients: WhatsAppClients = Object.keys(tokenData.auth).map(addLine);
215	  const listeners = new Set<LineAddedListener>();
216	  lineListeners.set(clients, listeners);
217	
218	  cloudAuthState.set(clients, {
219	    dispose: async () => {
220	      disposed = true;
221	      clearRenewalTimer();
222	      for (const state of lines.values()) {
223	        for (const sub of state.subscriptions) {
224	          sub.close();
225	        }
226	      }
227	      await Promise.allSettled(
228	        Array.from(lines.values()).map((s) => s.current.close())
229	      );
230	      lines.clear();
231	    },
232	  });
233	
234	  return clients;
235	}
236	
237	export async function disposeCloudAuth(
238	  clients: WhatsAppClients
239	): Promise<void> {
240	  const auth = cloudAuthState.get(clients);
241	  if (!auth) {
242	    return;
243	  }
244	  await auth.dispose();
245	  cloudAuthState.delete(clients);
246	}
