248	const buildClientProxy = (
249	  state: LineState,
250	  refresh: () => Promise<void>
251	): WhatsAppClient => {
252	  const forwarder = <T extends object>(pick: (c: WhatsAppClient) => T): T =>
253	    new Proxy({} as T, {
254	      get:
255	        (_, prop: string | symbol) =>
256	        async (...args: unknown[]) => {
257	          await refresh();
258	          const target = pick(state.current) as Record<
259	            string | symbol,
260	            unknown
261	          >;
262	          const fn = target[prop] as (...a: unknown[]) => unknown;
263	          return Reflect.apply(fn, pick(state.current), args);
264	        },
265	    });
266	
267	  const events = {
268	    fetchMissed: async (
269	      opts: Parameters<WhatsAppClient["events"]["fetchMissed"]>[0]
270	    ) => {
271	      await refresh();
272	      return state.current.events.fetchMissed(opts);
273	    },
274	    subscribe: (options?: SubscribeOptions) =>
275	      resubscribableStream(state, options),
276	  } as unknown as WhatsAppClient["events"];
277	
278	  return {
279	    events,
280	    media: forwarder((c) => c.media),
281	    messages: forwarder((c) => c.messages),
282	    close: async () => {
283	      for (const sub of state.subscriptions) {
284	        sub.close();
285	      }
286	      await state.current.close();
287	    },
288	    [Symbol.asyncDispose]: async () => {
289	      for (const sub of state.subscriptions) {
290	        sub.close();
291	      }
292	      await state.current.close();
293	    },
294	  };
295	};
296	
297	interface ResubscribeContext {
298	  emit: (event: WhatsAppEvent) => Promise<void>;
299	  getCurrent: () => WhatsAppClient;
300	  isClosed: () => boolean;
301	  options?: SubscribeOptions;
302	  setActive: (stream: TypedEventStream<WhatsAppEvent> | undefined) => void;
303	  swapVersion: () => number;
304	  waitForSwap: (version: number) => Promise<void>;
305	}
306	
307	type PumpResult = "closed" | "ended" | "error" | "swap";
308	
309	type NextResult =
310	  | { type: "next"; result: IteratorResult<WhatsAppEvent> }
311	  | { type: "error"; error: unknown };
312	
313	const settleNext = (
314	  next: Promise<IteratorResult<WhatsAppEvent>>
315	): Promise<NextResult> =>
316	  next.then(
317	    (result) => ({ type: "next", result }),
318	    (error) => ({ type: "error", error })
319	  );
320	
321	const closeStream = (stream: TypedEventStream<WhatsAppEvent>): void => {
322	  stream.close().catch(ignoreCleanupError);
323	};
324	
325	const returnIterator = (iterator: AsyncIterator<WhatsAppEvent>): void => {
326	  iterator.return?.(undefined).catch(ignoreCleanupError);
327	};
328	
329	const pumpOnce = async (ctx: ResubscribeContext): Promise<PumpResult> => {
330	  const sub = ctx.getCurrent().events.subscribe(ctx.options);
331	  const iterator = sub[Symbol.asyncIterator]();
332	  const swapVersion = ctx.swapVersion();
333	  ctx.setActive(sub);
334	  try {
335	    while (!ctx.isClosed()) {
336	      const result = await Promise.race([
337	        settleNext(iterator.next()),
338	        ctx.waitForSwap(swapVersion).then(() => ({ type: "swap" as const })),
339	      ]);
340	
341	      if (result.type === "swap") {
342	        closeStream(sub);
343	        returnIterator(iterator);
344	        return ctx.isClosed() ? "closed" : "swap";
345	      }
346	
347	      if (result.type === "error") {
348	        throw result.error;
349	      }
350	
351	      if (result.result.done) {
352	        return ctx.isClosed() ? "closed" : "ended";
353	      }
354	
355	      await ctx.emit(result.result.value);
356	    }
357	    return "closed";
358	  } catch (error) {
359	    closeStream(sub);
360	    returnIterator(iterator);
361	    streamLog.warn(
362	      "whatsapp event stream interrupted; resubscribing",
363	      {
364	        "spectrum.whatsapp.resubscribe_in_ms": RESUBSCRIBE_BACKOFF_MS,
365	        ...errorAttrs(error),
366	      },
367	      error
368	    );
369	    return ctx.isClosed() ? "closed" : "error";
370	  } finally {
371	    ctx.setActive(undefined);
372	  }
373	};
374	
375	// Returns a TypedEventStream that stays open across client swaps: on swap we
376	// close the underlying subscription and the worker loop re-subscribes against
377	// `state.current`.
378	const resubscribableStream = (
379	  state: LineState,
380	  options?: SubscribeOptions
381	): TypedEventStream<WhatsAppEvent> => {
382	  let closed = false;
383	  let active: TypedEventStream<WhatsAppEvent> | undefined;
384	  let swapVersion = 0;
385	  let wakeSwap: (() => void) | undefined;
386	
387	  const wake = () => {
388	    wakeSwap?.();
389	    wakeSwap = undefined;
390	  };
391	
392	  const requestResubscribe = () => {
393	    swapVersion += 1;
394	    wake();
395	    active?.close().catch(ignoreCleanupError);
396	  };
397	
398	  const source = stream<WhatsAppEvent>((emit, end) => {
399	    const ctx: ResubscribeContext = {
400	      emit,
401	      getCurrent: () => state.current,
402	      isClosed: () => closed,
403	      options,
404	      setActive: (s) => {
405	        active = s;
406	      },
407	      swapVersion: () => swapVersion,
408	      waitForSwap: (version) => {
409	        if (closed || swapVersion !== version) {
410	          return Promise.resolve();
411	        }
412	        return new Promise((resolve) => {
413	          wakeSwap = resolve;
414	        });
415	      },
416	    };
417	    const pump = (async () => {
418	      while (!closed) {
419	        const result = await pumpOnce(ctx);
420	        if (!closed && result !== "swap") {
421	          await new Promise((r) => setTimeout(r, RESUBSCRIBE_BACKOFF_MS));
422	        }
423	      }
424	      end();
425	    })();
426	
427	    return async () => {
428	      closed = true;
429	      wake();
430	      active?.close().catch(ignoreCleanupError);
431	      active = undefined;
432	      state.subscriptions.delete(subscription);
433	      await pump;
434	    };
435	  });
436	
437	  const subscription: LineSubscription = {
438	    close: () => {
439	      closed = true;
440	      wake();
441	      active?.close().catch(ignoreCleanupError);
442	    },
443	    swap: () => {
444	      // Force the worker loop to start a fresh RPC against state.current even
445	      // if the SDK iterator is stuck waiting for its old stream to finish.
446	      requestResubscribe();
447	    },
448	  };
449	  state.subscriptions.add(subscription);
450	
451	  return new TypedEventStream<WhatsAppEvent>(source, async () => {
452	    closed = true;
453	    wake();
454	    active?.close().catch(ignoreCleanupError);
455	    state.subscriptions.delete(subscription);
456	    await source.close();
457	  });
458	};
