    await clients[0]?.client.messages.markRead("wamid.1");

    expect(clients.map((c) => c.line)).toEqual(["phone-1", "phone-2"]);
    expect(added).toEqual(["phone-2"]);

    // The late-added line's proxy routes RPCs to its own raw client
