// A line removed from the project disappears from the refreshed payload:
// drop its entry so outbound routing falls back to an active line instead
// of sending through a client whose token will never refresh again.
const removeLine = async (
  phoneNumberId: string,
  state: LineState
): Promise<void> => {
  lines.delete(phoneNumberId);
  const index = clients.findIndex((c) => c.line === phoneNumberId);
  if (index !== -1) {
    clients.splice(index, 1);
  }
  for (const sub of state.subscriptions) {
    sub.close();
  }
  await state.current.close().catch(ignoreCleanupError);
  log.info("whatsapp line removed at runtime", {
    "spectrum.whatsapp.line": phoneNumberId,
  });
};

